@props([
    'name',
    'variant' => 'outline',
])

@php
    use App\Support\Bladex\Icon\IconPathResolver;
    use App\Support\Bladex\ProjectConfig;

    $resolvedName = IconPathResolver::normalizeName((string) $name);
    $iconPath = app(ProjectConfig::class)->resolvedIconsPath().'/'.$resolvedName.'.blade.php';

    if (! is_file($iconPath)) {
        throw new \RuntimeException("Icon [{$resolvedName}] is not installed. Run: php artisan bladex-components:icon {$resolvedName}");
    }

    $componentName = 'ui::icons.'.$resolvedName;
@endphp

<x-dynamic-component :component="$componentName" :variant="$variant" {{ $attributes }} />

@props([
    'variant' => 'outline',
])

@php
    use App\Support\Bladex\Icon\IconVariant;

    $normalizedVariant = IconVariant::normalize($variant);
    $iconClasses = IconVariant::classString($normalizedVariant);
    $strokeWidth = IconVariant::strokeWidth($normalizedVariant);
    $pixelSize = IconVariant::pixelSize($normalizedVariant);
@endphp

<svg
    {{ $attributes->class($iconClasses) }}
    width="{{ $pixelSize }}"
    height="{{ $pixelSize }}"
    data-icon
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    stroke-width="{{ $strokeWidth }}"
    stroke-linecap="round"
    stroke-linejoin="round"
    aria-hidden="true"
>
    {{ $slot }}
</svg>
